with candidate (n, title, artist, image_url, content, image_license, image_credit, image_page) as (
    values
    (1, '糸杉と麦畑', 'フィンセント・ファン・ゴッホ', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ce/Wheat-Field-with-Cypresses-%281889%29-Vincent-van-Gogh-Met.jpg/960px-Wheat-Field-with-Cypresses-%281889%29-Vincent-van-Gogh-Met.jpg', '1889年、南フランスのサン＝レミにある療養院に自ら入ったゴッホが、近くの麦畑を描いた作品です。黄色く実った麦の向こうに、暗い緑の糸杉が炎のように空へ伸び、渦を巻く白い雲と青い空が画面を包みます。ゴッホは弟テオへの手紙で、麦の穂と糸杉を描いた絵のことを伝えています。厚く盛り上げた絵の具の筆跡を追うと、風に揺れる畑の動きが感じられます。ニューヨークのメトロポリタン美術館が所蔵しています。', 'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Wheat-Field-with-Cypresses-(1889)-Vincent-van-Gogh-Met.jpg'),
    (2, '観楓図屏風', '狩野秀頼', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4a/Kano_Hideyori_-_Maple_Viewers_-_Google_Art_Project.jpg/960px-Kano_Hideyori_-_Maple_Viewers_-_Google_Art_Project.jpg', '京都・洛北の高雄で、清滝川のほとりの紅葉狩りを楽しむ人々を描いた六曲一隻の屏風で、16世紀後半の作とされる国宝です。川辺では茶売りの女性と子連れの客が、橋の上では笛を吹く男性と僧侶が、木陰では輪になって舞い酒宴を楽しむ男性たちが描かれています。雲の奥には神護寺の塔も見えます。応仁の乱で荒れた都が復興しはじめた頃の、のびやかな行楽の様子を伝える初期の風俗画です。東京国立博物館所蔵。', 'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Kano_Hideyori_-_Maple_Viewers_-_Google_Art_Project.jpg')
), fresh as (
    select c.*, row_number() over (order by c.n) as k
    from candidate c
    where not exists (select 1 from public.daily_columns d where d.title = c.title)
), free_day as (
    select day::date as display_date, row_number() over (order by day) as k
    from generate_series(
        (now() at time zone 'Asia/Tokyo')::date,
        (now() at time zone 'Asia/Tokyo')::date + 2
            + (select count(*)::int from public.daily_columns
               where display_date >= (now() at time zone 'Asia/Tokyo')::date),
        interval '1 day') as day
    where not exists (select 1 from public.daily_columns d where d.display_date = day::date)
)
insert into public.daily_columns (title, artist, image_url, content, image_license, image_credit, image_page, display_date)
select f.title, f.artist, f.image_url, f.content, f.image_license, f.image_credit, f.image_page, d.display_date
from fresh f join free_day d using (k)
on conflict (display_date) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('V&A企画「ディーヴァ展」、国立新美術館で詳細発表', 'V&A企画の巡回展が2027年3月から国立新美術館で。約280点で「ディーヴァ」200年史をたどる。', 'ロンドンのヴィクトリア＆アルバート博物館（V&A）が企画・制作し、世界各地を巡回してきた展覧会「ディーヴァ（DIVA）」が、国立新美術館で2027年3月24日から7月19日まで開催され、その詳細が発表された。19世紀のオペラ界から現代まで約200年にわたる「ディーヴァ」の歴史を、ファッションや社会、ジェンダーの観点から検証する。V&Aの所蔵品や個人コレクションから約280点が集まり、マリア・カラス、マリリン・モンロー、レディー・ガガ、ビョークらの衣装約60点を中心に紹介。日本独自の特別展示として「美輪明宏」「シスターフッド」も設けられる。', '', '展覧会', 'https://bijutsutecho.com/magazine/news/exhibition/33300',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('蜷川実花 with EiM、TOKYO NODEで大規模展', '新作中心の「望む世界、そして消えるもの」が2027年4月29日から虎ノ門のTOKYO NODEで開催。', '蜷川実花と、科学者・アーティスティックディレクターの宮田裕章らが集うクリエイティブチーム「EiM」による大規模展覧会「蜷川実花 with EiM展 望む世界、そして消えるもの Still, we are longing」が、東京・虎ノ門のTOKYO NODEで2027年4月29日から9月26日まで開催される。同所での展覧会は、81日間で25万人以上を動員した2023〜24年の「蜷川実花展 Eternity in a Moment 瞬きの中の永遠」以来、約3年ぶり。変わりゆく時代と人々の異なる願いをテーマに、新作を中心に構成される予定で、作品の詳細やチケット情報は今後発表される。', '', '展覧会', 'https://bijutsutecho.com/magazine/news/exhibition/33296',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('出光の美術賞、小舟氏『春の祭典』がグランプリ', '40歳までの若手を対象とする公募美術賞。受賞・入選作は12月9日から国立新美術館で展示。', '出光興産は、美術賞「Idemitsu Art Award 2026」のグランプリに小舟氏の『春の祭典』を選出し、グランプリを含む受賞作品8点と入選作品46点を決定した。同賞は40歳までの若手作家を対象とする公募制の美術賞で、1956年に「シェル美術賞」として創設され、今年で55回目。911名から1,174作品の応募があった。グランプリ作品はキャンバスに油彩の162.0×104.0cmの作品で、タイトルは同名のバレエ作品に由来する。小舟氏には賞金300万円が贈られる。受賞・入選作品は12月9日から国立新美術館で開かれる「Idemitsu Art Award 展 2026」で展示される。', '', '作品・作家', 'https://koubo.jp/article/135314',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('秋の褒章、現代美術家・奈良美智さんに紫綬褒章', '芸術・文化分野で活躍した人に贈られる紫綬褒章に、現代美術家の奈良美智さんが選ばれた。', '「秋の褒章」の受章者が発表され、芸術・文化の分野で活躍した人に贈られる紫綬褒章に、現代美術家の奈良美智さんらが選ばれた。奈良さんは大きな頭部と挑発的なまなざしが特徴的な子どもを描いた作品で国際的な評価を集め、2025年にはアメリカのタイム誌の「世界で最も影響力のある100人」にも選出された。受章について奈良さんは、国から褒められるために絵を描いてきたわけではないと述べつつ、これまで自分の絵を見てくれた人や支えてくれた人たちへの感謝を示し、賞をいただいたからといって自分の絵が昨日より良くなるわけではないとコメントを寄せた。', '', '作品・作家', 'https://www.kab.co.jp/news/article/17015888',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('老梅図襖', 'Old Plum', '狩野山雪', 'Kano Sansetsu',
        1647,
        (select slug from public.art_movements where slug = 'kano'),
        'メトロポリタン美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/69/%E8%80%81%E6%A2%85%E5%9B%B3%E8%A5%96-Old_Plum_MET_as1975.268.48a-d.AV2.jpg/960px-%E8%80%81%E6%A2%85%E5%9B%B3%E8%A5%96-Old_Plum_MET_as1975.268.48a-d.AV2.jpg', '京都・妙心寺の塔頭、天祥院にあった襖絵で、いまはニューヨークのメトロポリタン美術館が所蔵しています。金地の画面いっぱいに、老いた梅の幹が折れ曲がりながら横へ伸び、枝は直角に近い角度で上下に突き出します。自然の木をそのまま写すのではなく、垂直と水平を強調した幾何学的な形に組み直しているのが山雪らしいところです。師であり養父の山楽から京狩野の豪華な金碧画を受け継ぎながら、理知的で独特な造形へと踏み出した作品です。',
        'CC0', null, 'https://commons.wikimedia.org/wiki/File:老梅図襖-Old_Plum_MET_as1975.268.48a-d.AV2.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('観楓図屏風', 'Maple Viewing at Takao', '狩野秀頼', 'Kanō Hideyori',
        null,
        (select slug from public.art_movements where slug = 'kano'),
        '東京国立博物館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4a/Kano_Hideyori_-_Maple_Viewers_-_Google_Art_Project.jpg/960px-Kano_Hideyori_-_Maple_Viewers_-_Google_Art_Project.jpg', '紅葉の名所、京都の高雄で清滝川のほとりに集う人々を描いた国宝の屏風です。16世紀後半の作とされ、茶売りの女性、橋の上で笛を吹く男性と僧侶、輪になって舞う男性たちなど、行楽の楽しげな姿が濃い彩色で描かれています。雲の奥には神護寺の塔がのぞきます。漢画の技法を基礎にした狩野派の絵師が、名所の景色と当世の人々の暮らしを一つの画面に収めた作品で、のちの洛中洛外図など近世の風俗画へつながる早い例とされます。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Kano_Hideyori_-_Maple_Viewers_-_Google_Art_Project.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('松林図屏風', 'Pine Trees', '長谷川等伯', 'Hasegawa Tōhaku',
        null,
        (select slug from public.art_movements where slug = 'suiboku'),
        '東京国立博物館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/23/Hasegawa_Tohaku_-_Pine_Trees_%28Sh%C5%8Drin-zu_by%C5%8Dbu%29_-_right_hand_screen.jpg/960px-Hasegawa_Tohaku_-_Pine_Trees_%28Sh%C5%8Drin-zu_by%C5%8Dbu%29_-_right_hand_screen.jpg', '霧の中に松林が浮かび上がる、六曲一双の水墨の屏風で、国宝に指定されています。1593年ごろから95年ごろの作と考えられ、等伯が後継ぎと期待した息子・久蔵を亡くした時期にあたります。濃い墨で近くの松を、淡い墨で遠くの松を描き分け、何も描かない余白が湿った空気そのものに見えてきます。牧谿や雪舟に学んだ中国由来の水墨画を受け継ぎながら、日本の湿潤な風景と心情を表す独自の境地を開いた作品です。東京国立博物館所蔵。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Hasegawa_Tohaku_-_Pine_Trees_(Shōrin-zu_byōbu)_-_right_hand_screen.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('夜の梅', 'Woman Admiring Plum Blossoms at Night', '鈴木春信', 'Suzuki Harunobu',
        null,
        (select slug from public.art_movements where slug = 'ukiyo-e'),
        'メトロポリタン美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5e/MET_DP119555.jpg/960px-MET_DP119555.jpg', '夜の闇に白く咲く梅の花を、縁先に立つ若い女性が手燭をかざして見上げる場面を描いた多色摺りの木版画です。背景を黒一色で摺りつぶし、花や衣の模様には紙を凹凸だけで浮き出させる空摺りも使われています。細く華奢な人物と静かな情感は春信ならではのものです。春信は1765年ごろからの絵暦交換会をきっかけに多色摺りの錦絵を広めた絵師で、それまでの紅摺絵から豊かな色の版画へと浮世絵を変えました。メトロポリタン美術館所蔵。',
        'CC0', null, 'https://commons.wikimedia.org/wiki/File:MET_DP119555.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('長谷川等伯', 'Hasegawa Tōhaku', '等伯',
        1539, 1610, 'japan', array['suiboku']::text[],
        '能登出身で、狩野派と並ぶ長谷川派を築いた桃山時代の絵師。', '能登国七尾（いまの石川県）に生まれ、染物屋の長谷川家の養子として育ちました。若いころは地元で日蓮宗の寺のために仏画や肖像画を描き、1571年ごろ、養父母を亡くしたのち妻と息子の久蔵を連れて京都へ移りました。

京都では中国の水墨画などを学び、牧谿や雪舟から影響を受けました。千利休と交わり、大徳寺などの仕事を得て、狩野永徳とは競い合う間柄になります。1591年には豊臣秀吉が亡き子のために建てた祥雲寺の障壁画を一門で手がけ、長谷川派は狩野派に並ぶ勢力になりました。

1593年に久蔵を亡くし、そのころの作とされる水墨の「松林図屏風」（国宝、東京国立博物館）は代表作として知られます。晩年は「雪舟五代」を名乗り、1610年、徳川家康に招かれて着いた江戸で亡くなりました。', 'https://ja.wikipedia.org/wiki/%E9%95%B7%E8%B0%B7%E5%B7%9D%E7%AD%89%E4%BC%AF')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('鈴木春信', 'Suzuki Harunobu', '春信',
        1725, 1770, 'japan', array['ukiyo-e']::text[],
        '多色摺りの錦絵を広め、可憐な美人画で知られる江戸中期の浮世絵師。', '江戸中期の浮世絵師で、生年は1725年と推定されています。京都の西川祐信に学んだとも、江戸の西村重長の門人ともいわれ、江戸の神田白壁町に住み、平賀源内とも親しくしていました。

1765年ごろから、旗本の大久保巨川らが趣味で絵暦を交換する会を開き、彫師や摺師と組んで多くの色を重ねる木版画をつくりました。春信はその中心の絵師となり、ここから「錦絵」と呼ばれる多色摺りの浮世絵が広まりました。細身で手足の小さな可憐な人物、中間色を生かした叙情的な画面、古典の題材を当世の風俗に置き換えた見立絵が特徴です。

代表作に「座敷八景」「夜の梅」「雪中相合傘」などがあります。1770年に亡くなるまでのわずかな年月に多くの作品を残し、鳥居清長ら次の世代の絵師にも影響を与えました。', 'https://ja.wikipedia.org/wiki/%E9%88%B4%E6%9C%A8%E6%98%A5%E4%BF%A1')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('狩野山雪', 'Kano Sansetsu', '山雪',
        1590, 1651, 'japan', array['kano']::text[],
        '幾何学的な構図で知られる、京狩野の江戸初期の絵師。', '肥前国（いまの佐賀・長崎県）に生まれました。父を亡くしたのち狩野山楽に入門し、山楽の長男が早くに亡くなったため後継ぎとなり、山楽の娘の婿養子になりました。江戸へ移った狩野探幽らに対し、京都に残った「京狩野」を山楽とともに担いました。

垂直・水平の線や二等辺三角形を強調した、幾何学的で理知的な構図が持ち味です。妙心寺天球院の襖絵（重要文化財）、旧天祥院の「老梅図襖」（メトロポリタン美術館）、「寒山拾得図」、清水寺の「繋馬図絵馬」などが知られます。

蔵書家で学者肌の人物でもあり、日本の絵画史を研究しました。その草稿は子の狩野永納が完成させた『本朝画史』のもとになっています。', 'https://ja.wikipedia.org/wiki/%E7%8B%A9%E9%87%8E%E5%B1%B1%E9%9B%AA')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();
